  ('7eb8229b-f7df-57f1-b6ee-5a1266dd5ac5', '395050f8-2939-56a1-b7f8-64cc89ff0ba2', 7, 'val', 'Ali, Bea och Cem står i en kö. Ali står först och Cem står sist. Vem står i mitten?', '["Bea","Ali","Cem"]'::jsonb, '0'::jsonb, 'Ali är först och Cem är sist. Då står Bea i mitten, mellan dem.'),
  ('6ae5128b-ff0f-50e6-99a6-b191974500e0', '395050f8-2939-56a1-b7f8-64cc89ff0ba2', 8, 'ordna', 'Ordna formerna från färst hörn till flest hörn.', null, '["cirkel","triangel","kvadrat"]'::jsonb, 'En cirkel har inga hörn, en triangel har tre och en kvadrat har fyra.'),
  ('ed0e53a2-3c99-5e10-aed8-25670fa7fb17', '158af9bf-6e63-5198-86bf-e54ee5bf1894', 1, 'val', 'Hur många tiotal finns i talet 47?', '["4","7","47","40"]'::jsonb, '0'::jsonb, 'Talet 47 är 40 + 7. 40 är 4 tiotal.'),
  ('88cc639e-a627-5650-b0e5-7b47c5a88f29', '158af9bf-6e63-5198-86bf-e54ee5bf1894', 2, 'skriv', 'Talet 63 har 6 tiotal. Hur många ental har det?', null, '["3","tre","tre ental"]'::jsonb, 'Talet 63 är 60 + 3. 60 är 6 tiotal och 3 är 3 ental.'),
  ('15b42344-ea15-58bc-a75c-ed84a49e5e11', '158af9bf-6e63-5198-86bf-e54ee5bf1894', 3, 'val', 'Vilket tal är 5 tiotal och 2 ental?', '["52","25","502","7"]'::jsonb, '0'::jsonb, '5 tiotal är 50 och 2 ental är 2. 50 + 2 = 52.'),
  ('748f9f36-5016-5128-a6ee-bd53965985c0', '158af9bf-6e63-5198-86bf-e54ee5bf1894', 4, 'skriv', 'Vilket tal är 10 mer än 38?', null, '["48","fyrtioåtta"]'::jsonb, 'Tio mer är ett tiotal till. Tiotalen går från 3 till 4, så det blir 48.'),
  ('d83433ce-d2a4-56cc-b864-f4bda2e011d9', '158af9bf-6e63-5198-86bf-e54ee5bf1894', 5, 'val', 'Vilket tal är störst?', '["71","17","69","70"]'::jsonb, '0'::jsonb, 'Titta först på tiotalen. 71 och 70 har 7 tiotal. 71 har ett ental mer.'),
